pub(crate) fn locale_patterns(lang: &str) -> (&'static str, &'static str) {
    match lang {
        "ar" => (text(24539), text(24540)),
        "de" => (text(24539), text(24541)),
        "en" => (text(24539), text(24541)),
        "es" => (text(24539), text(24541)),
        "fr" => (text(24539), text(24541)),
        "gv" => (text(24539), text(24541)),
        "hi" => (text(24539), text(24541)),
        "it" => (text(24539), text(24541)),
        "ja" => (text(24539), text(24542)),
        "ko" => (text(24543), text(24541)),
        "ln" => (text(24539), text(24541)),
        "nl" => (text(24539), text(24541)),
        "pl" => (text(24539), text(24541)),
        "pt" => (text(24539), text(24541)),
        "ru" => (text(24539), text(24541)),
        "si" => (text(24539), text(24541)),
        "sl" => (text(24539), text(24541)),
        "sr" => (text(24539), text(24541)),
        "sv" => (text(24539), text(24541)),
        "th" => (text(24539), text(24541)),
        "zh" => (text(24544), text(24545)),
        _ => (text(24539), text(24541)),
    }
}

